# --- ヘルパー関数 ---
def load_pdf_data():
    if not os.path.exists(JSON_INPUT_FILE):
        return []

    with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
        reports = json.load(f)

    school_list = []
    subjects = ["japanese", "math", "science", "social_studies"]

    for report in reports:
        school_name = report.get('school_name', '不明な学校')
        school_name_abc = report.get('school_name_abc', '')

        school_info = {
            "name": school_name,
            "reports": []
        }

        for subject_en in subjects:
            pdf_path_relative = os.path.join(subject_en, f"{school_name_abc}.pdf")
            pdf_path_full = os.path.join(PDF_DIR, pdf_path_relative)

            if os.path.exists(pdf_path_full):
                subject_ja = SUBJECT_JA_MAP.get(subject_en, subject_en.capitalize())
                school_info["reports"].append({
                    "subject": subject_ja,
                    "pdf_filename": pdf_path_relative
                })

        if school_info["reports"]:
            school_list.append(school_info)

    return sorted(school_list, key=lambda x: x['name'])

def load_note_links():
    if not os.path.exists(JSON_INPUT_FILE):
        return []

    with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
        reports = json.load(f)

    school_list = []
    ordered_subjects = ["japanese", "math", "science", "social_studies"] 

    for report in reports:
        school_name = report.get('school_name', '不明な学校')
        school_info = {
            "name": school_name,
            "reports": [] 
        }

        for subject_en in ordered_subjects: 
            note_url = report.get('past_exam_reports', {}).get(subject_en, {}).get('note_url')
            subject_ja = SUBJECT_JA_MAP.get(subject_en, subject_en.capitalize())

            school_info["reports"].append({
                "subject": subject_ja,
                "note_url": note_url 
            })

        school_list.append(school_info)

    return sorted(school_list, key=lambda x: x['name'])


def _get_filtered_schools(subject=None):
    """Helper function to load and filter schools based on subject."""
    all_schools = load_note_links()
    subjects = list(SUBJECT_MAP.keys())

    if subject and subject in subjects:
        # Filter by subject
        filtered_schools = []
        for school in all_schools:
            filtered_reports = [
                report for report in school['reports'] 
                if report['subject'] == subject and report['note_url']
            ]
            if filtered_reports:
                new_school_info = school.copy()
                new_school_info['reports'] = filtered_reports
                filtered_schools.append(new_school_info)
        return filtered_schools
    else:
        # If no subject filter, return all schools that have at least one report with a URL
        filtered_schools = []
        for school in all_schools:
            if any(report['note_url'] for report in school['reports']):
                filtered_schools.append(school)
        return filtered_schools

